package com.scrollshot.lite;
import android.accessibilityservice.*;import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.HardwareBuffer;import android.os.*;import android.provider.MediaStore;import android.content.ContentValues;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import java.text.*;import java.util.*;
public class CaptureService extends AccessibilityService {
 static CaptureService instance; Handler h=new Handler(Looper.getMainLooper());WindowManager wm; TextView bubble; TextView closeButton; LinearLayout overlay;boolean running=false;int index=0,max=10,delay=700;String session;
 @Override protected void onServiceConnected(){instance=this;showOverlay();}
 @Override public void onAccessibilityEvent(android.view.accessibility.AccessibilityEvent e){} @Override public void onInterrupt(){}
 @Override public void onDestroy(){running=false;removeOverlay();instance=null;super.onDestroy();}
 void removeOverlay(){if(overlay!=null){try{wm.removeView(overlay);}catch(Exception ignored){}overlay=null;bubble=null;closeButton=null;}}
 public void showOverlay(){if(overlay!=null)return;wm=(WindowManager)getSystemService(WINDOW_SERVICE);overlay=new LinearLayout(this);overlay.setOrientation(LinearLayout.VERTICAL);overlay.setGravity(Gravity.CENTER_VERTICAL);bubble=new TextView(this);bubble.setText("▶");bubble.setTextSize(18);bubble.setTextColor(0xffffffff);bubble.setGravity(Gravity.CENTER);bubble.setBackgroundColor(0xff1677ee);overlay.addView(bubble,new LinearLayout.LayoutParams(76,76));closeButton=new TextView(this);closeButton.setText("✕");closeButton.setTextSize(18);closeButton.setTextColor(0xffffffff);closeButton.setGravity(Gravity.CENTER);closeButton.setBackgroundColor(0xff30343b);overlay.addView(closeButton,new LinearLayout.LayoutParams(76,76));WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,android.graphics.PixelFormat.TRANSLUCENT);p.gravity=Gravity.RIGHT|Gravity.CENTER_VERTICAL;wm.addView(overlay,p);bubble.setOnClickListener(v->{if(running)stop();else start();});closeButton.setOnClickListener(v->{running=false;h.removeCallbacksAndMessages(null);removeOverlay();});}
 void start(){running=true;index=0;max=getSharedPreferences("MainActivity",0).getInt("count",10);delay=getSharedPreferences("MainActivity",0).getInt("delay",700);session=new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.US).format(new Date());bubble.setText("■");h.postDelayed(this::capture,350);}
 void stop(){running=false;if(bubble!=null)bubble.setText("▶");Toast.makeText(this,"캡처 "+index+"장 저장",Toast.LENGTH_SHORT).show();}
 void capture(){if(!running)return;overlay.setVisibility(View.INVISIBLE);h.postDelayed(()->takeScreenshot(Display.DEFAULT_DISPLAY,getMainExecutor(),new TakeScreenshotCallback(){
 public void onSuccess(ScreenshotResult result){try{HardwareBuffer hb=result.getHardwareBuffer();Bitmap hw=Bitmap.wrapHardwareBuffer(hb,result.getColorSpace());Bitmap bmp=hw==null?null:hw.copy(Bitmap.Config.ARGB_8888,false);hb.close();if(bmp==null)throw new IOException("bitmap unavailable");save(bmp);bmp.recycle();index++;}catch(Exception e){h.post(()->{if(overlay!=null)overlay.setVisibility(View.VISIBLE);stop();Toast.makeText(CaptureService.this,"저장 실패: "+e.getMessage(),Toast.LENGTH_LONG).show();});return;}h.post(()->{if(overlay!=null)overlay.setVisibility(View.VISIBLE);if(index>=max){stop();return;}scroll();});}
 public void onFailure(int code){h.post(()->{if(overlay!=null)overlay.setVisibility(View.VISIBLE);stop();Toast.makeText(CaptureService.this,"캡처 실패: "+code,Toast.LENGTH_LONG).show();});}
 }),180);}
 void scroll(){android.util.DisplayMetrics dm=getResources().getDisplayMetrics();float x=dm.widthPixels*.5f,y1=dm.heightPixels*.78f,y2=dm.heightPixels*.27f;Path path=new Path();path.moveTo(x,y1);path.lineTo(x,y2);GestureDescription.StrokeDescription stroke=new GestureDescription.StrokeDescription(path,0,520);dispatchGesture(new GestureDescription.Builder().addStroke(stroke).build(),new GestureResultCallback(){@Override public void onCompleted(GestureDescription g){h.postDelayed(()->{if(running)capture();},delay);}@Override public void onCancelled(GestureDescription g){stop();}},null);}
 void save(Bitmap b)throws IOException{ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"scrollshot_"+session+"_"+String.format(Locale.US,"%03d",index+1)+".png");v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/ScrollShotLite");v.put(MediaStore.Images.Media.IS_PENDING,1);Uri uri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(uri==null)throw new IOException("MediaStore insert failed");try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null||!b.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("PNG encode failed");}catch(Exception e){getContentResolver().delete(uri,null,null);throw new IOException(e);}ContentValues done=new ContentValues();done.put(MediaStore.Images.Media.IS_PENDING,0);getContentResolver().update(uri,done,null,null);}
}